def solve(g_in):
    H,W=len(g_in),len(g_in[0])
    sr=[i for i,r in enumerate(g_in) if len(set(r))==1 and r[0]!=0]
    sc=[j for j in range(W) if all(g_in[i][j]==g_in[0][j] and g_in[0][j]!=0 for i in range(H))]
    def groups(seps,n):
        res=[];cur=[]
        for x in range(n):
            if x not in set(seps): cur.append(x)
            else: if cur: res.append(cur);cur=[]
        if cur: res.append(cur)
        return res
    rb,cb=groups(sr,H),groups(sc,W)
    # template: seed shape (nonzero cells within a cell, excluding sep color) with max count, whole grid
    best=None
    for bi,b in enumerate(rb):
        for cj,c in enumerate(cb):
            sh=set()
            for i in b:
                for j in c:
                    v=g_in[i][j]
                    if v!=0 and v!=g_in[sr[0]][sc[0]]:
                        sh.add((i-min(b),j-min(c)))
            if best is None or len(sh)>len(best[0]): best=(sh,)
            elif len(sh)==len(best[0]):
                # tie: prefer wider bbox
                bh=max(r for r,c in sh)-min(r for r,c in sh)+1
                bw=max(c for r,c in sh)-min(c for r,c in sh)+1
                tbh=max(r for r,c in best[0])-min(r for r,c in best[0])+1
                tbw=max(c for r,c in best[0])-min(c for r,c in best[0])+1
                if bh>=tbh and bw>=tbw: best=(sh,)
    tmpl=best[0]
    # bottom-align within 4x4 cell
    m=max(r for r,c in tmpl); tmpl=[(r-m,cc) for r,cc in tmpl]
    tm={ (r,c) for r,c in tmpl }
    # band colors: most common nonzero non-sep color in band cells
    colcnt={}
    for bi,b in enumerate(rb):
        cc={}
        for cj,c in enumerate(cb):
            for i in b:
                for j in c:
                    v=g_in[i][j]
                    if v!=0 and v!=g_in[sr[0]][sc[0]]: cc[v]=cc.get(v,0)+1
        colcnt[bi]=max(cc,key=cc.get) if cc else None
    out=[row[:] for row in g_in]
    for bi,b in enumerate(rb):
        col=colcnt[bi]
        if col is None: continue
        for cj,c in enumerate(cb):
            for r,i in enumerate(b):
                for q,j in enumerate(c):
                    out[i][j]= col if (r,q) in tm else 0
    return out
