# dump per-tile stamped offsets as seen in go: find for each seeded tile which single translation of template (recolored to seed color) equals the actual stamp exactly.
for dk in ['Demo pair 1','Demo pair 2']:
    gi=G[dk+' input']; go=G[dk+' output']
    H=len(gi); W=len(gi[0])
    sr={i for i in range(H) if len({x for x in gi[i]})==1 and gi[i][0]!=0}
    sc={j for j in range(W) if len({gi[i][j] for i in range(H)})==1 and gi[0][j]!=0}
    sepv={gi[r][cc] for r in sr for cc in range(W)}|{gi[rr][c] for c in sc for rr in range(H)}
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            v=gi[i][j]
            if v!=0 and v not in sepv and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;comp=[]
                while st:
                    x,y=st.pop();comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and not seen[a][b] and gi[a][b]==v:
                                seen[a][b]=True;st.append((a,b))
                comps.append((v,comp))
    tm=None
    for v,cp in comps:
        mr=min(r for r,_ in cp); mc=min(c for _,c in cp)
        n=(max(r for r,_ in cp)-mr+1)*(max(c for _,c in cp)-mc+1)
        if len(cp)<n:
            tm=[(r-mr,c-mc) for r,c in sorted(cp)]; break
    Rb=bands([i for i in range(H) if i not in sr]); Cb=bands([j for j in range(W) if j not in sc])
    res=[]
    for rl in Rb:
        for cl in Cb:
            sset=[(i-rl[0],j-cl[0]) for i in rl for j in cl if gi[i][j] not in sepv]
            if not sset: continue
            scol=gi[rl[0]][cl[0]]
            # exact match candidates: translated template set == stamp cells, all recolored to scol, AND no extra colored cell in the tile outside
            stcells={(aa,bb) for aa,bb in [(i-rl[0],j-cl[0]) for i in rl for j in cl]}
            good=[]
            for dr in range(-4,5):
                for dc in range(-4,5):
                    tcells={(rl[0]+dr+r,cl[0]+dc+c) for r,c in tm}
                    if tcells=={(rl[0]+a,cl[0]+b) for a,b in stcells}:
                        good.append((dr,dc))
            res.append(((len(rl),len(cl)),scol,tuple(sorted(good))))
    print('===',dk,'tmpl rel size',len(tm))
    for x in res: print('   shape',x[0],'seedcol',x[1],'offsets',x[2])

