    for i in range(len(gi)):
        for j in range(len(gi[0])):
            v=gi[i][j]
            if v!=0 and v not in sepv and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;comp=[]
                while st:
                    x,y=st.pop();comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<len(gi) and 0<=b<len(gi[0]) and not seen[a][b] and gi[a][b]==v:
                                seen[a][b]=True;st.append((a,b))
                res.append((v,comp))
    return res
def find_sep(gi):
    H,W=len(gi),len(gi[0])
    sr={i for i in range(H) if len(set(gi[i]))==1 and gi[i][0]!=0}
    sc={j for j in range(W) if len({gi[i][j] for i in range(H)})==1 and gi[0][j]!=0}
    sv=set()
    for r in sr: sv |= {gi[r][c] for c in range(len(gi[0]))}
    for c in sc: sv |= {gi[r][c] for r in range(len(gi))}
    return sr,sc,sv
def bands(idx):
    res=[];cur=[]
    for x in idx:
        if cur and x==cur[-1]+1: cur.append(x)
        else:
            if cur: res.append(cur)
            cur=[x]
    if cur: res.append(cur)
    return res
for dk in ['Demo pair 1','Demo pair 2']:
    gi=G[dk+' input']; go=G[dk+' output']
    sr,sc,sepv=find_sep(gi)
    comps=comps_of(gi,sepv)
    big=max(comps,key=lambda c:len(c[1])); tmpl=list(big[1]); tc=big[0]
    tr=min(r for r,_ in tmpl); tcl=min(c for _,c in tmpl)
    th=max(r for r,_ in tmpl)-tr+1; tw=max(c for _,c in tmpl)-tcl+1
    print('===',dk,'tmpl rel shape:')
    for r_ in range(th):
        print('  ', ''.join('#' if (r_,c_) in {(r-tr,tcl+c_) for r,c in tmpl} else '.' for c_ in range(tw)))
    for rl in bands([i for i in range(len(gi)) if i not in sr]):
        for cl in bands([j for j in range(len(gi[0])) if j not in sc]):
            scol=None
            for i in rl:
                for j in cl:
                    if gi[i][j]!=0 and gi[i][j] not in sepv and gi[i][j]!=tc: scol=gi[i][j]
            if scol is None: continue
            srel={(i-rl[0],j-cl[0]) for i in rl for j in cl if gi[i][j]==scol}
            stamp_rel={(i-rl[0],j-cl[0]) for i in rl for j in cl if go[i][j]==scol}
            sTL=(min(p[0] for p in srel),min(p[1] for p in srel))
            stL=(min(p[0] for p in stamp_rel),min(p[1] for p in stamp_rel))
            # template rel TL is (0,0) by construction
            print('   scol',scol,'seedTLrel',sTL,'stampTLrel',stL,'diff',tuple(a-b for a,b in zip(sTL,stL)))

import os,re,collections
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(gi,sepv):
    seen=[[False]*len(gi[0]) for _ in gi];res=[]
    for i in range(len(gi)):
        for j in range(len(gi[0])):
            v=gi[i][j]
            if v!=0 and v not in sepv and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;comp=[]
                while st:
                    x,y=st.pop();comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<len(gi) and 0<=b<len(gi[0]) and not seen[a][b] and gi[a][b]==v:
                                seen[a][b]=True;st.append((a,b))
                res.append((v,comp))
    return res
def find_sep(gi):
    H,W=len(gi),len(gi[0])
    sr={i for i in range(H) if len(set(gi[i]))==1 and gi[i][0]!=0}
    sc={j for j in range(W) if len({gi[i][j] for i in range(H)})==1 and gi[0][j]!=0}
    sv=set()
    for r in sr: sv |= {gi[r][c] for c in range(len(gi[0]))}
    for c in sc: sv |= {gi[r][c] for r in range(len(gi))}
    return sr,sc,sv
def bands(idx):
    res=[];cur=[]
    for x in idx:
        if cur and x==cur[-1]+1: cur.append(x)
        else:
            if cur: res.append(cur)
            cur=[x]
    if cur: res.append(cur)
    return res
def solve(gi):
    H,W=len(gi),len(gi[0])
    sr,sc,sepv=find_sep(gi)
    comps=comps_of(gi,sepv)
    big=max(comps,key=lambda c:len(c[1]))
    tmpl=list(big[1]); tc=big[0]
    tr=min(r for r,_ in tmpl); tcl=min(c for _,c in tmpl)
    rbands=bands([i for i in range(H) if i not in sr]); cbands=bands([j for j in range(W) if j not in sc])
    out=[row[:] for row in gi]
    for rl in rbands:
        for cl in cbands:
            r0,r1=rl[0],rl[-1]; c0,c1=cl[0],cl[-1]
            scol=None
            for i in range(r0,r1+1):
                for j in range(c0,c1+1):
                    if gi[i][j]!=0 and gi[i][j] not in sepv and gi[i][j]!=tc:
                        scol=gi[i][j]
            if scol is None: continue
            # clear tile interior of any nonzero content (seed erased, per observed output)
            for i in range(r0,r1+1):
                for j in range(c0,c1+1):
                    out[i][j]=0
            h=r1-r0+1; w=c1-c0+1
            dr=(h-th)//2; dc=(w-tw)//2
            for r,c in tmpl:
                nr=r0+dr+(r-tr); nc=c0+dc+(c-tcl)
                if r0<=nr<=r1 and c0<=nc<=c1:
                    out[nr][nc]=scol
    return out
for dk in ['Demo pair 1','Demo pair 2']:
    f=solve(G[dk+' input'])
    ok=f==G[dk+' output']
    print(dk,'match:',ok)
    if not ok:
        diffs=[(i,j,f[i][j],G[dk+' output'][i][j]) for i in range(len(f)) for j in range(len(f[0])) if f[i][j]!=G[dk+' output'][i][j]]
        print(' ndiff',len(diffs),diffs[:10])
